/**
 * 琴键练习分区。
 *
 * 七个方向（Sound / Words / Meaning / Structure / Context / Culture /
 * Expression）在界面上太碎，一眼读不出差别。这里按「学习时真正会分开练的四件事」
 * 合并成四个大类，每个大类仍然保留原来的细分说明：
 *
 *   1. Sound      语音      ← Sound
 *   2. Words      词汇与语义 ← Words + Meaning（点开单词探索页）
 *   3. Structure  结构与语篇 ← Structure + Context
 *   4. Expression 表达与文化 ← Expression + Culture
 *
 * 顺序即低音区到高音区的顺序：43 个琴键平均落在四个分区里。
 * `panel` 标记哪些分区有独立的练习页（目前只有词汇区打开单词探索页），
 * 这样「第几个分区会打开单词页」不再是一个写死在组件里的魔法下标。
 */

const PIANO_KEY_COUNT = 43;

export const PIANO_NOTES = [
  {
    label: "Do",
    zh: "哆",
    skill: "Sound",
    nameZh: "语音",
    detail: "发音 · 音标 · 重音 · 语调",
    panel: null,
  },
  {
    label: "Re",
    zh: "来",
    skill: "Words",
    nameZh: "词汇与语义",
    detail: "词汇 · 搭配 · 一词多义 · 语境",
    panel: "words",
  },
  {
    label: "Mi",
    zh: "咪",
    skill: "Structure",
    nameZh: "结构与语篇",
    detail: "语法 · 句法 · 长难句 · 语料",
    panel: null,
  },
  {
    label: "Fa",
    zh: "发",
    skill: "Expression",
    nameZh: "表达与文化",
    detail: "写作 · 翻译 · 口语 · 英美文化",
    panel: null,
  },
] as const;

export type PianoPracticePanel = NonNullable<
  (typeof PIANO_NOTES)[number]["panel"]
>;

export interface PianoNote {
  label: (typeof PIANO_NOTES)[number]["label"];
  zh: (typeof PIANO_NOTES)[number]["zh"];
  skill: (typeof PIANO_NOTES)[number]["skill"];
  nameZh: (typeof PIANO_NOTES)[number]["nameZh"];
  detail: (typeof PIANO_NOTES)[number]["detail"];
  panel: (typeof PIANO_NOTES)[number]["panel"];
  noteIndex: number;
  octave: number;
  midi: number;
  frequency: number;
}

export function pianoNoteForKey(index: number): PianoNote {
  const safeIndex = Math.max(0, Math.floor(index));
  const noteIndex = practiceRegionForKey(safeIndex);
  const note = PIANO_NOTES[noteIndex] ?? PIANO_NOTES[0];
  const midi = 48 + safeIndex;
  const octave = Math.floor(midi / 12) - 1;

  return {
    ...note,
    noteIndex,
    octave,
    midi,
    frequency: 440 * 2 ** ((midi - 69) / 12),
  };
}

export function practiceRegionForKey(index: number): number {
  const safeIndex = Math.min(
    PIANO_KEY_COUNT - 1,
    Math.max(0, Math.floor(index)),
  );
  return Math.min(
    PIANO_NOTES.length - 1,
    Math.floor((safeIndex * PIANO_NOTES.length) / PIANO_KEY_COUNT),
  );
}

export function firstKeyForPracticeRegion(region: number): number {
  const safeRegion = Math.min(
    PIANO_NOTES.length - 1,
    Math.max(0, Math.floor(region)),
  );
  return Math.ceil((safeRegion * PIANO_KEY_COUNT) / PIANO_NOTES.length);
}

/** 该分区是否有独立练习页。选中琴键时用它决定要不要打开对应面板。 */
export function practicePanelForRegion(
  region: number,
): PianoPracticePanel | null {
  if (!Number.isFinite(region)) return null;
  const safeRegion = Math.min(
    PIANO_NOTES.length - 1,
    Math.max(0, Math.floor(region)),
  );
  return PIANO_NOTES[safeRegion]?.panel ?? null;
}
