import { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { isRoomRoute } from "../../motion/motionConfig";
import StaggeredMenu from "../reactbits/vendor/StaggeredMenu/StaggeredMenu";
import RecentShelf from "./RecentShelf";
import "./persistent-dock.css";

/**
 * The right-hand plaque names the three spaces the room is made of, the way a
 * study is signed rather than navigated: LIBRARY is where the knowledge lives,
 * PIANO is how it comes back, DRAWER is where it is kept.
 *
 * `zh` carries the Chinese name under the English one, and `caption` is the
 * one-line inventory of what the space holds. Both exist so the plaque reads
 * as a room sign — not as a web menu with a list of links.
 */
const directory = [
  {
    label: "LIBRARY",
    zh: "知识书架",
    caption: "English knowledge",
    ariaLabel: "Library — English knowledge",
    children: [
      {
        label: "Linguistics",
        ariaLabel: "Open Linguistics",
        path: "/shelf?book=core-language",
      },
      {
        label: "Literature",
        ariaLabel: "Open Literature",
        path: "/shelf?book=core-literature",
      },
      {
        label: "Translation",
        ariaLabel: "Open Translation",
        path: "/shelf?book=core-translation",
      },
      {
        label: "Lexicology",
        ariaLabel: "Open Lexicology",
        path: "/shelf?book=core-lexicology",
      },
      {
        label: "Writing skills",
        ariaLabel: "Open Writing skills",
        path: "/shelf?book=core-writing",
      },
    ],
  },
  {
    label: "PIANO",
    zh: "智能复习",
    caption: "Review mode",
    ariaLabel: "Piano — review mode",
    children: [
      {
        label: "Concepts",
        ariaLabel: "Review concepts",
        path: "/shelf?book=core-language",
      },
      {
        label: "Vocabulary",
        ariaLabel: "Review vocabulary",
        path: "/vocabulary",
      },
      {
        label: "Reading",
        ariaLabel: "Review reading",
        path: "/reading",
      },
      {
        label: "Translation",
        ariaLabel: "Review translation",
        path: "/shelf?book=core-translation",
      },
      {
        label: "Writing",
        ariaLabel: "Review writing",
        path: "/shelf?book=core-writing",
      },
    ],
  },
  {
    label: "DRAWER",
    zh: "我的知识库",
    caption: "My archive",
    ariaLabel: "Drawer — my archive",
    children: [
      {
        label: "Notes",
        ariaLabel: "Open Notes drawer",
        path: "/shelf?drawer=notes",
      },
      {
        // Matches the drawer's own label (DRAWER_META.materials) so the plaque
        // and the drawer it opens say the same word.
        label: "Cards",
        ariaLabel: "Open Knowledge cards drawer",
        path: "/shelf?drawer=materials",
      },
      {
        label: "Collection",
        ariaLabel: "Open Collection drawer",
        path: "/shelf?drawer=collection",
      },
    ],
  },
] as const;

function isActive(pathname: string, search: string, path: string) {
  if (path.includes("?")) {
    const [targetPath, targetSearch] = path.split("?");
    return pathname === targetPath && search === `?${targetSearch}`;
  }
  if (path === "/shelf") {
    return isRoomRoute(pathname) && search === "";
  }
  if (path === "/library") {
    return pathname === "/library" || pathname.startsWith("/book/");
  }
  return pathname === path || pathname.startsWith(`${path}/`);
}

export function PersistentDock() {
  const location = useLocation();
  const navigate = useNavigate();
  const [menuSignal, setMenuSignal] = useState(0);
  const [dismissed, setDismissed] = useState(false);
  // The room keeps its own menu button on the brand dock, so the floating
  // toggle would be a second way to open the same thing. The landing has its
  // own nav and runs its own scroll choreography — the dock has no business
  // there at all.
  const isRoom = isRoomRoute(location.pathname);
  const onLanding = location.pathname === "/";

  useEffect(() => {
    const openMenu = () => {
      setDismissed(false);
      setMenuSignal((current) => current + 1);
    };
    window.addEventListener("inkflow:open-menu", openMenu);
    return () => window.removeEventListener("inkflow:open-menu", openMenu);
  }, []);

  const menuItems = useMemo(
    () =>
      directory.map((item) => ({
        label: item.label,
        zh: item.zh,
        caption: item.caption,
        ariaLabel: item.ariaLabel,
        link: "#",
        children: item.children.map((child) => ({
          label: child.label,
          ariaLabel: child.ariaLabel,
          link: child.path,
          className: isActive(location.pathname, location.search, child.path)
            ? "is-active"
            : undefined,
        })),
      })),
    [location.pathname, location.search],
  );

  if (onLanding) return null;

  return (
    <StaggeredMenu
      className="inkflow-staggered-menu"
      isFixed
      position="right"
      items={menuItems}
      panelExtra={<RecentShelf onNavigate={() => setDismissed(true)} />}
      colors={["#b0b1cf", "#d7d4e6", "#f1e2d2"]}
      accentColor="#65647f"
      displaySocials={false}
      displayItemNumbering={false}
      menuButtonColor="#f8f0e8"
      openMenuButtonColor="#fffaf3"
      logoUrl="/inkflow-logo.png"
      hideToggle={isRoom}
      openSignal={menuSignal}
      dismissed={dismissed}
      onItemClick={(item) => {
        const targetPath = item.link;
        if (!targetPath.startsWith("/")) return;
        setDismissed(true);
        // Both shelf deep links land on the same route the reader is already
        // on, so the router alone would not re-run the open-book/open-drawer
        // logic. The event is what actually opens the thing; navigate() only
        // keeps the URL honest.
        if (
          targetPath.startsWith("/shelf?drawer=") ||
          targetPath.startsWith("/shelf?book=")
        ) {
          window.dispatchEvent(
            new CustomEvent("inkflow:shelf-action", {
              detail: { path: targetPath, at: Date.now() },
            }),
          );
        }
        navigate(targetPath);
      }}
    />
  );
}
