import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import DriftWall from "../reactbits/vendor/DriftWall/DriftWall";
import { BOOKS, BOOK_COVER_IMAGES } from "../study/books";

/**
 * 「最近学习」——右侧说明牌里的第四块，但不是导航分组：它是一面缓慢漂移的
 * 书墙，把最近在读的书直接摊开给读者看。
 *
 * 用书墙而不是列表，是因为前三个分组的条目都是「去哪里」，这里要表达的是
 * 「读到哪儿了」——封面比书名更快认出来。
 */
export function RecentShelf({ onNavigate }: { onNavigate?: () => void }) {
  const navigate = useNavigate();

  const items = useMemo(
    () =>
      BOOKS.map((book) => ({
        id: book.id as string,
        image: BOOK_COVER_IMAGES[book.id],
        title: book.zhTitle || book.title,
      })),
    [],
  );

  return (
    <section className="recent-shelf" aria-label="Recently studied">
      <span
        className="sm-panel-groupLabel sm-panel-itemLabel recent-shelf__label"
        data-index="4"
      >
        RECENT
        <small className="sm-panel-groupZh">最近学习</small>
      </span>
      <span className="sm-panel-groupCaption">Recently studied</span>
      <div className="recent-shelf__wall">
        <DriftWall
          items={items}
          columns={3}
          tileWidth={88}
          tileHeight={126}
          gap={12}
          radius={8}
          tilt={8}
          turn={-11}
          perspective={900}
          depth={70}
          speed={22}
          variance={0.36}
          parallax={0.32}
          lift={38}
          fade={0.5}
          dim={0.95}
          overlayColor="#e2deee"
          tileBg="#efeaf4"
          onTileClick={(item: { id?: string } | undefined) => {
            if (!item?.id) return;
            onNavigate?.();
            navigate(`/book/${item.id}`);
          }}
        />
      </div>
    </section>
  );
}

export default RecentShelf;
