import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  MoveHorizontal,
  Play,
} from "lucide-react";
import { motion } from "motion/react";
import FlipCard from "../reactbits/vendor/FlipCard/FlipCard";
import { cn } from "../../lib/cn";
import { IPA_CARDS, type IpaCard } from "./languageLabData";
import type { CollectedWord } from "./WordsExplorer";

function speakWord(word: string) {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(word);
  utterance.lang = "en-GB";
  utterance.rate = 0.8;
  window.speechSynthesis.speak(utterance);
}

function IpaCardFront({ card }: { card: IpaCard }) {
  return (
    <div className="ipa-flip-face ipa-flip-face--front">
      <span className="ipa-flip-face__type">{card.type}</span>
      <strong>{card.symbol}</strong>
      <small>{card.letter}</small>
      <div>
        <span>{card.manner}</span>
        <span>{card.place}</span>
      </div>
      <em>
        <MoveHorizontal size={11} />
        Flip for explanation
      </em>
    </div>
  );
}

function IpaCardBack({ card }: { card: IpaCard }) {
  return (
    <div className="ipa-flip-face ipa-flip-face--back">
      <span className="ipa-flip-face__type">Explanation</span>
      <h3>{card.symbol}</h3>
      <p>{card.note}</p>
      <dl>
        <div>
          <dt>Manner</dt>
          <dd>{card.manner}</dd>
        </div>
        <div>
          <dt>Place</dt>
          <dd>{card.place}</dd>
        </div>
        <div>
          <dt>Example</dt>
          <dd>{card.example}</dd>
        </div>
      </dl>
    </div>
  );
}

export function IpaGallery({
  savedIds,
  onBack,
  onSave,
}: {
  savedIds: string[];
  onBack: () => void;
  onSave: (item: CollectedWord) => void;
}) {
  return (
    <motion.div
      className="ipa-gallery"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
    >
      <header className="language-lab__subheader">
        <button type="button" onClick={onBack}>
          <ArrowLeft size={15} />
          Sound Lab
        </button>
        <div>
          <span className="eyebrow">Collect sounds, not chapters</span>
          <h2>IPA Gallery</h2>
        </div>
        <span>
          {IPA_CARDS.filter((card) => savedIds.includes(card.id)).length} saved
        </span>
      </header>

      <div className="ipa-gallery__grid">
        {IPA_CARDS.map((card, index) => {
          const saved = savedIds.includes(card.id);
          return (
            <motion.article
              key={card.id}
              className="ipa-flip-item"
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
            >
              <FlipCard
                front={<IpaCardFront card={card} />}
                back={<IpaCardBack card={card} />}
                axis="y"
                flipOnClick
                draggable
                tilt
                tiltMax={8}
                glare
                glareOpacity={0.3}
                hoverScale={1.032}
                perspective={1000}
                stiffness={180}
                damping={21}
                width={260}
                height={300}
                radius={14}
                background="#fffaf4"
                color="#4e4d69"
                shadow
                shadowColor="#565473"
                shadowOpacity={0.18}
                ariaLabel={`${card.symbol} IPA card. Flip to see explanation.`}
              />
              <footer className="ipa-flip-item__actions">
                <button
                  type="button"
                  onClick={() => speakWord(card.example)}
                >
                  <Play size={12} />
                  {card.example}
                </button>
                <button
                  type="button"
                  className={cn(saved && "is-saved")}
                  disabled={saved}
                  onClick={() =>
                    onSave({
                      id: card.id,
                      title: `${card.symbol} · ${card.example}`,
                      meta: `IPA card · ${card.manner} · ${card.place}`,
                      kind: "save",
                    })
                  }
                >
                  {saved ? <Check size={12} /> : <BookmarkPlus size={12} />}
                  {saved ? "Collected" : "Save"}
                </button>
              </footer>
            </motion.article>
          );
        })}
      </div>
    </motion.div>
  );
}
