/**
 * 一本书的章节清单。语言学的章节就是 Language Map 上的五条路径（那本书打开的
 * 是 Language Lab，不是主题列表），其余四本用 CORE_BOOK_TOPICS。
 * 「当前学习」的进度 = 台账里点开过的章节 / 这份清单，不是写死的百分比。
 */
function bookTopics(bookId: string): string[] {
  const base = bookBaseId(bookId);
  if (base === "core-language") {
    return LANGUAGE_MAP_NODES.map((node) => node.label);
  }
  return CORE_BOOK_TOPICS[base] ?? [];
}
