function createArchiveBook(
  row: ShelfRow,
  rowIndex: number,
  volumeIndex: number,
  color: string,
  thickness: number,
  height: number,
): ReaderBook {
  const archive =
    SHELF_ARCHIVE_BOOKS[
      (rowIndex * 5 + volumeIndex) % SHELF_ARCHIVE_BOOKS.length
    ] ?? SHELF_ARCHIVE_BOOKS[0];
  const slug = archive.title.toLowerCase().replace(/[^a-z]+/g, "-");

  return {
    id: `shelf-${row.number}-${slug}-${volumeIndex}` as ReaderBook["id"],
    title: archive.title,
    zhTitle: archive.zhTitle,
    author: "InkFlow Archive",
    spine: color,
    pageTint: "#FBF6EF",
    slot: [0, rowIndex],
    coverWidth: 0.18,
    height,
    thickness,
    lean: ((volumeIndex % 5) - 2) * 0.006,
    editable: false,
    source: "",
    translation: "",
  };
}

// A private study shelf, not a library: each row carries a handful of volumes
// with visible air between them, and stops well short of the plank's right edge.
// Spacing the stock books ~2x wider and capping the rows is what turns a packed
// stockroom into a shelf someone chose.
const ARCHIVE_GAP = 0.1;
/**
 * Stock volumes per row. Deliberately a private shelf rather than a stockroom:
 * six spines and then air, so the row reads as chosen rather than filled.
 */
const ARCHIVE_ROW_LIMIT = 6;
/**
 * 「01 当前学习」「04 学习档案」两层的左半边藏书量。比别的层少两本，右端让给
 * 平放的书摞和档案盒 —— 那才是这两层真正的重点。
 */
const FEATURE_FILLER_LIMIT = 4;
/** 功能物件的右端锚点：从这儿往左摆，和下面的抽屉格一样收到同一条边。 */
const FEATURE_ANCHOR_X = 0.72;
/** Functional volumes are one set, so they sit a touch tighter than stock. */
const CORE_GAP = 0.075;
/** Where every row's first spine goes. Rows align on this left margin. */
const ROW_ORIGIN_X = -1.48;

/** Spine thickness of functional volume `index`, before its own spread. */
function coreThickness(index: number) {
  return 0.18 + ((index % 3) - 1) * 0.012;
}

/**
 * 04 学习档案那层的档案盒，和 01 空着时的提示牌。两者都不是书，但都走同一套
 * 「能打开」的语言（金圈箭头 + 悬停抬起来），所以用同一个板子去渲染。
 */
const ARCHIVE_BOX_ID = "shelf-archive-box";
const CURRENT_INVITE_ID = "shelf-invite";
/** 一层里最多平放几本正在读的书。再多就成书堆了，不是「当前在学习」。 */
const CURRENT_LEARNING_LIMIT = 3;
const LYING_BOOK_DEPTH = 0.42;
/** 稳定引用：没有功能物件的层靠它避免每帧重建书脊纹理。 */
const EMPTY_FEATURES: ShelfFeatureVolume[] = [];

