/**
 * 一本「正在读」的书 = 同一本书的副本，id 带 `#now`，平放在 01 层。副本只是
 * 几何上的另一份：点哪一份都是打开同一本书（身份统一用 base id）。
 */
function lyingBookFeature(book: ReaderBook, stack: number): ShelfFeatureVolume {
  return {
    book: { ...book, id: `${book.id}#now` as ReaderBook["id"] },
    lying: true,
    thickness: book.thickness,
    height: book.height,
    depth: LYING_BOOK_DEPTH,
    // 一摞书稍微错开一点：既像随手放下的，也避免三块热区完全重叠。
    dx: -stack * 0.02,
    dy: stack * (book.thickness + 0.008),
    dz: stack * 0.028,
  };
}

