export function createShelfVolumes(
  row: ShelfRow,
  rowIndex: number,
  features: ShelfFeatureVolume[] = [],
): ShelfVolume[] {
  // Detect a functional row from the books themselves rather than from the
  // count: the Language Garden row is scheduled to grow from 3 to 5 volumes,
  // and `row.books.length === 3` would silently flip this to a filler row.
  const coreRow = row.books.some((book) => book.id.startsWith("core-"));
  const featureRow = features.length > 0;
  const volumes: ShelfVolume[] = [];
  // The Language Garden row holds the five functional books and nothing else —
  // no stock books framing them in. That row is the answer to "which of these
  // can I actually open?", and padding it with decoration is exactly what makes
  // the shelf read as ornament. It keeps the left margin the other rows use and
  // simply stops early, so the empty right half reads as room to grow rather
  // than as a row that ran out.
  let cursor = ROW_ORIGIN_X;
  let archiveIndex = 0;

  const addArchiveVolume = (x: number, thickness: number, height: number) => {
    const color =
      FILLER_PALETTE[
        (archiveIndex + rowIndex * 2) % FILLER_PALETTE.length
      ] ?? COLORS.riceFrost;
    const book = createArchiveBook(
      row,
      rowIndex,
      archiveIndex,
      color,
      thickness,
      height,
    );
    volumes.push({
      book,
      key: String(book.id),
      x,
      thickness,
      height,
      depth: 0.37 + ((archiveIndex + rowIndex) % 3) * 0.018,
      z: 0.05 + (archiveIndex % 3) * 0.019,
      lean: (((archiveIndex + rowIndex) % 5) - 2) * 0.006,
      core: false,
    });
    archiveIndex += 1;
  };

  row.books.forEach((book, index) => {
    const coreBook = book.id.startsWith("core-");
    // Functional volumes get a small, deliberate spread in thickness and lean so
    // the row reads as five bound books rather than five identical slabs. Kept
    // under ~3% of thickness and ~0.5 degrees, so nothing overlaps or falls over.
    const thickness = coreBook
      ? coreThickness(index)
      : 0.13 + ((index + rowIndex) % 4) * 0.024;
    const height = coreBook
      ? 0.68
      : 0.52 + ((index * 3 + rowIndex) % 5) * 0.055;
    const x = cursor + thickness / 2;
    cursor += thickness + (coreBook ? CORE_GAP : ARCHIVE_GAP);
    volumes.push({
      book,
      key: String(book.id),
      x,
      thickness,
      height,
      depth: 0.42,
      z: 0.12 + (index % 2) * 0.022,
      lean: coreBook ? ((index % 3) - 1) * 0.008 : book.lean,
      core: coreBook,
    });
  });

  // The functional row keeps its right side open — air is the point there.
  // Feature rows stop two volumes earlier for the same reason: the right end
  // belongs to the pile of books being read / the archive box.
  const fillerLimit = featureRow ? FEATURE_FILLER_LIMIT : ARCHIVE_ROW_LIMIT;
  while (!coreRow && cursor < 0.72 && archiveIndex < fillerLimit) {
    const thickness = 0.12 + ((archiveIndex + rowIndex) % 3) * 0.045;
    const height = 0.55 + ((archiveIndex * 2 + rowIndex) % 4) * 0.07;
    addArchiveVolume(cursor + thickness / 2, thickness, height);
    cursor += thickness + ARCHIVE_GAP;
  }

  // 台账里长出来的物件，从右端锚点往左摆。平放的书横向占地是 height（书脊长度），
  // 竖直方向只剩 thickness —— 这也正是「平放」在几何上的全部含义。
  for (const feature of features) {
    const width = feature.lying ? feature.height : feature.thickness;
    volumes.push({
      book: feature.book,
      key: String(feature.book.id),
      x: FEATURE_ANCHOR_X - width / 2 + (feature.dx ?? 0),
      thickness: feature.thickness,
      height: feature.height,
      depth: feature.depth,
      z: 0.14 + (feature.dz ?? 0),
      lean: feature.lying ? LYING_LEAN : 0,
      core: true,
      lying: feature.lying,
      label: feature.label,
      lift: feature.dy ?? 0,
    });
  }

  return volumes.sort((a, b) => a.x - b.x);
}

