  const [quotes, setQuotes] = useState<QuoteItem[]>(loadQuotes);
  const [skinId, setSkinId] = useState<SkinId>(loadSkinId);
  const skin = SKIN_PRESETS[skinId];
  // Flips once the Canvas has painted its first real frame; drives the loading
  // plate over the shelf area and signals the intro curtain (scene-ready.ts).
