function DrawerFolder3D({
  index,
  open,
  color,
  skin,
}: {
  index: number;
  open: boolean;
  color: string;
  skin: SkinPreset;
}) {
  const group = useRef<THREE.Group>(null);
  const progress = useRef(0);
  const delay = index * 0.12;

  useFrame((state, delta) => {
    if (!group.current) return;
    progress.current = THREE.MathUtils.damp(
      progress.current,
      open ? 1 : 0,
      open ? 8 : 11,
      delta,
    );
    const staggered = THREE.MathUtils.smoothstep(
      progress.current,
      delay,
      Math.min(1, delay + 0.64),
    );
    const hover = Math.sin(state.clock.elapsedTime * 1.8 + index * 0.9) * 0.008;

    group.current.position.y = THREE.MathUtils.damp(
      group.current.position.y,
      staggered * (0.62 + index * 0.03) + hover,
      9,
      delta,
    );
    group.current.position.z = THREE.MathUtils.damp(
      group.current.position.z,
      staggered * (0.18 + index * 0.05),
      9,
      delta,
    );
    group.current.rotation.x = THREE.MathUtils.damp(
      group.current.rotation.x,
      staggered * -0.18,
      10,
      delta,
    );
    group.current.rotation.z = THREE.MathUtils.damp(
      group.current.rotation.z,
      staggered * (index - 1.5) * 0.035,
      10,
      delta,
    );
  });

  return (
    <group
      ref={group}
      position={[-0.18 + index * 0.18, 0, 0]}
    >
      <mesh position={[0, 0.1, 0]} castShadow receiveShadow>
        <boxGeometry args={[0.23, 0.35, 0.024]} />
        <meshStandardMaterial color={color} roughness={0.74} />
      </mesh>
      <mesh position={[-0.06, 0.285, 0]} castShadow>
        <boxGeometry args={[0.085, 0.032, 0.028]} />
        <meshStandardMaterial color={color} roughness={0.72} />
      </mesh>
      <mesh position={[0, 0.1, 0.016]}>
        <planeGeometry args={[0.19, 0.27]} />
        <meshStandardMaterial color={skin.three.folderPaper} roughness={0.9} />
      </mesh>
      {[-0.07, -0.025, 0.02].map((lineY) => (
        <mesh key={lineY} position={[0, 0.1 + lineY, 0.019]}>
          <planeGeometry args={[0.13, 0.007]} />
          <meshBasicMaterial
            color={skin.three.folderInk}
            transparent
            opacity={0.34}
            depthWrite={false}
          />
        </mesh>
      ))}
    </group>
  );
}

