function AccountSection({ account }: { account: InkflowAccount }) {
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState("");
  const [codeSent, setCodeSent] = useState(false);
  const phoneReady = /^1\d{10}$/.test(phone);

  const sendCode = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!phoneReady) return;
    if (await account.sendCode(phone)) setCodeSent(true);
  };
  const submitCode = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (code.length !== 6) return;
    if (await account.signInWithCode(phone, code)) {
      setCode("");
      setCodeSent(false);
    }
  };

  if (account.status === "signed-in" && account.user) {
    return (
      <section className="study-shelf__guide-section study-shelf__account">
        <h4>账号</h4>
        <p className="study-shelf__account-line">
          <strong>{account.user.displayName}</strong>
          <small>{account.user.phoneMasked ?? "开发者体验账号"}</small>
        </p>
        <p className="study-shelf__guide-note">
          抽屉便条跟着这个账号走：刷新页面、换台设备用同一个手机号登录，都还在。
          没登录时便条只存在本机，功能不受影响。
        </p>
        <button
          type="button"
          className="study-shelf__account-action"
          disabled={account.busy}
          onClick={() => void account.signOut()}
        >
          退出登录
        </button>
      </section>
    );
  }

  return (
    <section className="study-shelf__guide-section study-shelf__account">
      <h4>账号 · 便条同步</h4>
      <p>
        不登录也能用：便条只存在这台设备上。登录之后便条按账号保存，
        刷新或者换台设备都还在。现在只有开发者登录和手机验证码两种方式。
      </p>
      <button
        type="button"
        className="study-shelf__account-action"
        disabled={account.busy}
        onClick={() => void account.signInWithDeveloper()}
      >
        开发者登录（一键体验）
      </button>
      <form className="study-shelf__account-form" onSubmit={sendCode}>
        <input
          type="tel"
          value={phone}
          inputMode="numeric"
          maxLength={11}
          placeholder="手机号"
          aria-label="手机号"
          onChange={(event) =>
            setPhone(event.target.value.replace(/\D/g, "").slice(0, 11))
          }
        />
        <button type="submit" disabled={account.busy || !phoneReady}>
          {codeSent ? "重新发送" : "获取验证码"}
        </button>
      </form>
      {codeSent ? (
        <form className="study-shelf__account-form" onSubmit={submitCode}>
          <input
            type="text"
            value={code}
            inputMode="numeric"
            maxLength={6}
            placeholder="6 位验证码"
            aria-label="验证码"
            onChange={(event) =>
              setCode(event.target.value.replace(/\D/g, "").slice(0, 6))
            }
          />
          <button type="submit" disabled={account.busy || code.length !== 6}>
            登录
          </button>
        </form>
      ) : null}
      {account.devCode ? (
        <p className="study-shelf__account-hint">
          还没接短信通道，开发环境的验证码是 {account.devCode}。
        </p>
      ) : null}
      {account.error ? (
        <p className="study-shelf__account-hint is-error" role="status">
          {account.error}
        </p>
      ) : null}
    </section>
  );
}

