/**
 * 悬停一本书时浮出来的小卡片。
 *
 * 这里的进度、词条数、笔记数从前是写死的（BOOK_META）—— 和用户真正做了什么
 * 没关系，也就没法解释「为什么是 64%」。现在只报台账里真发生过的事：点开过
 * 几个章节、最近一章是什么、最近一次学是什么时候。没学过就直说没开始。
 */
function BookInfoCard({
  book,
  record,
  onContinue,
}: {
  book: ReaderBook | null;
  record: BookStudyRecord | null;
  onContinue: (book: ReaderBook) => void;
}) {
  const bookId = book ? bookBaseId(String(book.id)) : "";
  const topics = book ? bookTopics(bookId) : [];
  const explored = record
    ? record.topics.filter(
        (topic) => topics.length === 0 || topics.includes(topic),
      ).length
    : 0;
  const progress = topics.length
    ? Math.round((explored / topics.length) * 100)
    : 0;

  return (
    <AnimatePresence>
      {book ? (
        <motion.aside
          className="study-book-card"
          initial={false}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 6 }}
          transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
        >
          <span className="study-book-card__kicker">
            Current Learning · 当前学习
          </span>
          <strong>{book.title}</strong>
          <small>{book.zhTitle}</small>
          <div className="study-book-card__progress" aria-hidden="true">
            <i style={{ width: `${progress}%` }} />
          </div>
          <div className="study-book-card__meta">
            <span>
              已探索{" "}
              <b>
                {explored}/{topics.length || 0}
              </b>
            </span>
            <span>
              最近学习 <b>{record ? formatRelativeTime(record.lastAt) : "—"}</b>
            </span>
          </div>
          <span className="study-book-card__chapter">
            最近章节 <b>{record?.lastTopic ?? "还没有开始"}</b>
          </span>
          <button type="button" onClick={() => onContinue(book)}>
            继续学习 <ArrowUpRight size={13} />
          </button>
        </motion.aside>
      ) : null}
    </AnimatePresence>
  );
}

