import {
  Navigate,
  Route,
  Routes,
  useLocation,
  useNavigate,
} from "react-router-dom";
import { Archive, ChevronRight, CloudOff, X } from "lucide-react";
import { lazy, Suspense, useEffect, type ReactNode } from "react";
import { BookReaderPage } from "./components/book/BookReaderPage";
import { LiquidGlass } from "./components/reactbits/LiquidGlass";
import { HomeLobby } from "./components/home/HomeLobby";
import { LandingPage } from "./components/landing/LandingPage";
import { SiteIntro } from "./components/intro/SiteIntro";
import { PersistentDock } from "./components/navigation/PersistentDock";
import { cn } from "./lib/cn";
import { useInkFlow } from "./store/inkflow";

const SpaceLibrary = lazy(() =>
  import("./components/library/SpaceLibrary").then((module) => ({
    default: module.SpaceLibrary,
  })),
);
const CorpusPage = lazy(() =>
  import("./components/corpus/CorpusPage").then((module) => ({
    default: module.CorpusPage,
  })),
);
const VocabularyPage = lazy(() =>
  import("./components/vocabulary/VocabularyPage").then((module) => ({
    default: module.VocabularyPage,
  })),
);
const ChapterLibrary = lazy(() =>
  import("./components/reading/ChapterLibrary").then((module) => ({
    default: module.ChapterLibrary,
  })),
);
const ChapterReader = lazy(() =>
  import("./components/reading/ChapterReader").then((module) => ({
    default: module.ChapterReader,
  })),
);
const ComponentLabPage = lazy(() =>
  import("./components/reactbits/ComponentLabPage").then((module) => ({
    default: module.ComponentLabPage,
  })),
);

function ArchiveDrawer() {
  const navigate = useNavigate();
  const { archiveOpen, setArchiveOpen } = useInkFlow();
  if (!archiveOpen) return null;

  return (
    <div
      className="drawer-backdrop"
      role="presentation"
      onClick={() => setArchiveOpen(false)}
    >
      <LiquidGlass
        as="aside"
        className="archive-drawer"
        role="dialog"
        aria-modal="true"
        aria-label="Archive"
        intensity="strong"
        onClick={(event) => event.stopPropagation()}
      >
        <header>
          <div>
            <span className="eyebrow">Stored beneath the desk</span>
            <h2>Archive</h2>
          </div>
          <button
            type="button"
            className="icon-button"
            onClick={() => setArchiveOpen(false)}
            aria-label="Close archive"
          >
            <X size={18} />
          </button>
        </header>
        <div className="archive-list">
          {[
            ["Last summer’s reading list", "18 notes · archived 2 weeks ago"],
            ["Interview vocabulary, first draft", "42 phrases · archived last month"],
            ["Teaching observation notes", "9 pages · archived in June"],
          ].map(([title, meta]) => (
            <button
              type="button"
              key={title}
              onClick={() => {
                setArchiveOpen(false);
                navigate("/library");
              }}
            >
              <Archive size={18} />
              <span>
                <strong>{title}</strong>
                <small>{meta}</small>
              </span>
              <ChevronRight size={16} />
            </button>
          ))}
        </div>
      </LiquidGlass>
    </div>
  );
}

function OfflineBanner() {
  const { apiOnline, deepseekConfigured, bootstrapped } = useInkFlow();
  const { pathname } = useLocation();
  // The landing is a closed composition — its nav sits dead centre and the
  // banner would land right on top of it. The notice belongs to the room,
  // where the reader is actually working against the API.
  if (pathname === "/") return null;
  if (!bootstrapped || apiOnline) return null;
  return (
    <div className="offline-banner">
      <CloudOff size={15} />
      <span>
        Local mode is active. The interface and sample corpus remain available;
        configure the API to enable DeepSeek and persistent sync.
      </span>
      <small>{deepseekConfigured ? "API unavailable" : "No API key"}</small>
    </div>
  );
}

function Toast() {
  const { toast } = useInkFlow();
  return (
    <div className={cn("toast", toast && "is-visible")} role="status">
      {toast?.message}
    </div>
  );
}

function LazyRoute({ children }: { children: ReactNode }) {
  return <Suspense fallback={null}>{children}</Suspense>;
}

export function App() {
  const bootstrap = useInkFlow((state) => state.bootstrap);

  useEffect(() => {
    void bootstrap();
  }, [bootstrap]);

  return (
    <div className="inkflow-app">
      <SiteIntro />
      <OfflineBanner />
      <div className="motion-route-stage" data-motion-root>
        <Routes>
          {/* The landing owns the front door; the 3D room is one click in. */}
          <Route path="/" element={<LandingPage />} />
          <Route path="/shelf" element={<HomeLobby />} />
          <Route path="/study" element={<Navigate to="/shelf" replace />} />
          <Route
            path="/inkverse/:bookId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/library"
            element={
              <LazyRoute>
                <SpaceLibrary />
              </LazyRoute>
            }
          />
          <Route
            path="/write/:noteId"
            element={<Navigate to="/library" replace />}
          />
          <Route
            path="/write/:noteId/:pageId"
            element={<Navigate to="/library" replace />}
          />
          <Route path="/book/:bookId" element={<BookReaderPage />} />
          <Route
            path="/corpus"
            element={
              <LazyRoute>
                <CorpusPage />
              </LazyRoute>
            }
          />
          <Route
            path="/reading"
            element={
              <LazyRoute>
                <ChapterLibrary />
              </LazyRoute>
            }
          />
          <Route
            path="/reading/:chapterId"
            element={
              <LazyRoute>
                <ChapterReader />
              </LazyRoute>
            }
          />
          <Route path="/practice" element={<Navigate to="/" replace />} />
          <Route
            path="/vocabulary"
            element={
              <LazyRoute>
                <VocabularyPage />
              </LazyRoute>
            }
          />
          <Route
            path="/components"
            element={
              <LazyRoute>
                <ComponentLabPage />
              </LazyRoute>
            }
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
      <PersistentDock />
      <ArchiveDrawer />
      <Toast />
    </div>
  );
}
