import { Menu } from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation, useSearchParams } from "react-router-dom";
import { SplitText } from "../reactbits/vendor";
import { whenSceneReady } from "../../lib/scene-ready";
import {
  WoodenBookshelf,
  type ShelfDrawerId,
} from "./WoodenBookshelf";

/** How long after the room paints before the plate rises. The intro curtain
 *  takes ~1.3 s to lift off a ready scene; the plate should arrive behind it,
 *  not while the room is still covered. */
const PLATE_DELAY_MS = 900;

/** Safety net for a scene that never reports a frame (2D fallback, no WebGL). */
const PLATE_GRACE_MS = 6_000;

export function HomeLobby() {
  const [searchParams] = useSearchParams();
  const location = useLocation();
  const [shelfAction, setShelfAction] = useState(0);
  const [plateIn, setPlateIn] = useState(false);
  const drawerParam = searchParams.get("drawer");
  const initialDrawer: ShelfDrawerId | null =
    drawerParam === "notes" ||
    drawerParam === "materials" ||
    drawerParam === "collection"
      ? drawerParam
      : null;
  const initialBookId = searchParams.get("book");

  useEffect(() => {
    const handleShelfAction = () => setShelfAction((value) => value + 1);
    window.addEventListener("inkflow:shelf-action", handleShelfAction);
    return () =>
      window.removeEventListener("inkflow:shelf-action", handleShelfAction);
  }, []);

  // The plate is part of walking into the room, so it waits for the room to be
  // there. `whenSceneReady` fires immediately when the scene is already up
  // (returning readers, or a same-session nav), which keeps the plate from
  // being stranded off-screen on repeat visits.
  useEffect(() => {
    let timer = 0;
    let grace = 0;
    const reveal = () => {
      window.clearTimeout(grace);
      timer = window.setTimeout(() => setPlateIn(true), PLATE_DELAY_MS);
    };
    const stopWaiting = whenSceneReady(reveal);
    // The 2D fallback and any WebGL failure never report a painted frame, so
    // the plate arms itself on a timer too — same reason the intro curtain has
    // a grace period. The name of the room is not worth withholding.
    grace = window.setTimeout(reveal, PLATE_GRACE_MS);
    return () => {
      stopWaiting();
      window.clearTimeout(timer);
      window.clearTimeout(grace);
    };
  }, []);

  return (
    <div className="home-lobby home-lobby--shelf">
      <header className="home-lobby__brand-dock">
        <button
          type="button"
          className="home-lobby__brand home-lobby__brand--compact home-lobby__brand--menu"
          aria-label="打开功能菜单"
          aria-haspopup="menu"
          onClick={() => window.dispatchEvent(new Event("inkflow:open-menu"))}
        >
          <span className="home-lobby__brand-mark" aria-hidden="true">
            <img src="/inkflow-logo.png" alt="" />
            <span className="home-lobby__brand-menuGlyph">
              <Menu size={11} strokeWidth={2.6} />
            </span>
          </span>
          <span>
            <SplitText
              tag="strong"
              text="InkFlow"
              className="home-lobby__brand-title"
              delay={42}
              duration={0.56}
              ease="power3.out"
              splitType="chars"
              from={{ opacity: 0, y: 20, rotateX: -32 }}
              to={{ opacity: 1, y: 0, rotateX: 0 }}
              threshold={0}
              rootMargin="0px"
              textAlign="left"
            />
            <small>Moonlit study room</small>
          </span>
        </button>
      </header>

      <main className="home-lobby__main home-lobby__main--shelf home-lobby__main--study-room">
        <header
          className={`home-lobby__room-head${plateIn ? " is-in" : ""}`}
          aria-live="polite"
        >
          <span className="home-lobby__room-plate">
            <span className="home-lobby__room-name">Library</span>
            <span className="home-lobby__room-hint">
              Explore your knowledge space
            </span>
          </span>
        </header>

        <WoodenBookshelf
          actionKey={`${location.key}:${shelfAction}`}
          initialDrawer={initialDrawer}
          initialBookId={initialBookId}
        />
      </main>
    </div>
  );
}
